3.角谷猜想

输入一个整数\(n\)(\(1≤n≤1000\)) ，如果奇数则\(n=3n+1\)然后步数+1，偶数则\(n=\frac{n}{2}\)然后步数+1，直到
\(n=1\)。

输出一共要多少步。

本题推荐最大时长：8分钟

题目输入案例：10

输出结果案例：6

答案

C

#include <stdio.h>
int main(){
	int n;						// 当前的数
	int step = 0;				// 步数
	scanf("%d", &n);
	while (n != 1) {			// 没变成 1 就继续
		if (n % 2 == 0) {		// 偶数
			n = n / 2;			// 折半
		} else {				// 奇数
			n = 3 * n + 1;		// 3n+1
		}
		step++;					// 每变一次，步数 +1
	}
	printf("%d\n", step);
	return 0;
}

C++

#include <iostream>
int main(){
	int n;						// 当前的数
	int step = 0;				// 步数
	std::cin >> n;
	while (n != 1) {			// 没变成 1 就继续
		if (n % 2 == 0) {		// 偶数
			n = n / 2;			// 折半
		} else {				// 奇数
			n = 3 * n + 1;		// 3n+1
		}
		step++;					// 每变一次，步数 +1
	}
	std::cout << step << "\n";
	return 0;
}


4.6174数字黑洞

 1. 选择任意一个四位数，数字不能全相同（如1111不行）。
 2. 将数字重新排列，组成最大数和最小数。
 3. 用最大数减去最小数，得到一个新的四位数（不足四位时在高位补零）。
 4. 重复上述步骤，最终结果总会收敛到6174。

例如，选择数字6321：

第一次：6321 - 1236 = 5085

第二次：8550 - 0558 = 7992

第三次：9972 - 2799 = 7173

第四次：7731 - 1377 = 6354

第五次：6543 - 3456 = 3087

第六次：8730 - 0378 = 8352

第七次：8532 - 2358 = 6174

本题推荐最大时长：30分钟(难度偏大)

题目输入案例：6321

输出结果案例：7

答案

思路分四步：拆出 4 个数字 → 排序 → 拼出最大数和最小数 → 相减。排序用的是 3.2 习题里"三数比较"的交换思路。

C

#include <stdio.h>
int main(){
	int n;						// 当前的数
	int step = 0;				// 迭代步数
	int a, b, c, d, t;			// 4 个数字 + 交换用的临时变量
	int max, min;
	if (scanf("%d", &n) != 1) return 0;	// 保险：读不到就结束
	while (n != 6174) {			// 没收敛到 6174 就继续
		// 1. 拆位
		a = n % 10;				// 个位
		b = n / 10 % 10;		// 十位
		c = n / 100 % 10;		// 百位
		d = n / 1000;			// 千位（不足四位时自动是 0 = 补零）
		// 2. 排序成 a<=b<=c<=d
		if (a > b) { t = a; a = b; b = t; }
		if (b > c) { t = b; b = c; c = t; }
		if (c > d) { t = c; c = d; d = t; }
		if (a > b) { t = a; a = b; b = t; }
		if (b > c) { t = b; b = c; c = t; }
		if (a > b) { t = a; a = b; b = t; }
		// 3. 拼出最大数和最小数
		min = a * 1000 + b * 100 + c * 10 + d;	// 升序 = 最小
		max = d * 1000 + c * 100 + b * 10 + a;	// 倒序 = 最大
		// 4. 相减，进入下一轮
		n = max - min;
		step++;					// 步数 +1
		// 如果你想更完整的观看整个流程，可以取消下一行注释，看每一次计算过程
		// printf("%d - %d = %d\n", max, min, n);
	}
	printf("%d\n", step);
	return 0;
}

C++

#include <iostream>
int main(){
	int n;						// 当前的数
	int step = 0;				// 迭代步数
	int a, b, c, d, t;			// 4 个数字 + 交换用的临时变量
	int max, min;
	if (!(std::cin >> n)) return 0;	// 保险：读不到就结束
	while (n != 6174) {			// 没收敛到 6174 就继续
		a = n % 10;				// 个位
		b = n / 10 % 10;		// 十位
		c = n / 100 % 10;		// 百位
		d = n / 1000;			// 千位（不足四位时自动是 0 = 补零）
		if (a > b) { t = a; a = b; b = t; }
		if (b > c) { t = b; b = c; c = t; }
		if (c > d) { t = c; c = d; d = t; }
		if (a > b) { t = a; a = b; b = t; }
		if (b > c) { t = b; b = c; c = t; }
		if (a > b) { t = a; a = b; b = t; }
		min = a * 1000 + b * 100 + c * 10 + d;	// 升序 = 最小
		max = d * 1000 + c * 100 + b * 10 + a;	// 倒序 = 最大
		n = max - min;
		step++;					// 步数 +1
		// 如果你想更完整的观看整个流程，可以取消下一行注释，看每一次计算过程
		// std::cout << max << " - " << min << " = " << n << "\n";
	}
	std::cout << step << "\n";
	return 0;
}


5.约瑟夫环

\(n\) 个人围成一圈，从 1 号开始报数：报到 \(m\) 的人出列，下一个人重新从 1 报数，如此循环，直到圈里只剩一个人。输出最后剩下的那个人的编号。

输入两个整数 n m（\(1 \le m \le n \le 100\)）。

本题推荐最大时长：30分钟(难度偏大)

题目输入案例：5 3

输出结果案例：4

答案

思路：用一个数组标记每个人还在不在圈里，报数时跳过已经出列的人，数满 m 个就把那个人标记出列；只剩一个人时循环结束，把那个下标输出。

C

#include <stdio.h>
int main(){
	int n, m;					// 人数、报数上限
	int a[105];					// a[i]=1 表示 i 号还在圈里
	int alive;					// 圈里还剩多少人
	int cur;					// 当前报到哪个人
	int cnt;					// 这一轮已经报了几个数
	int i;						// 找幸存者用的下标
	scanf("%d %d", &n, &m);
	i = 1;
	while (i <= n) {			// 先让所有人都"在圈里"
		a[i] = 1;
		i++;
	}
	alive = n;					// 一开始 n 个人都在
	cur = 0;					// 先置 0，进入循环会先 +1，所以从 1 号开始数
	while (alive > 1) {			// 只剩一个人就停
		cnt = 0;				// 每轮重新从 1 报数
		while (cnt < m) {		// 数满 m 个人才停
			cur++;				// 走到下一个人
			if (cur > n) cur = 1;	// 出圈尾就回到 1 号
			if (a[cur] == 1) cnt++;	// 只有还活着的人才算数
		}
		a[cur] = 0;				// 报满 m：出列
		alive--;				// 圈里少一个人
	}
	i = 1;
	while (a[i] != 1) i++;		// 找到唯一还活着的人
	printf("%d", i);
	return 0;
}

